  const chart = '(?:charts?|candles?|candlesticks?|bars?|timeframe|time frame|tf)\\b';
  let m = t.match(/(\d{1,3})\s*-?\s*(?:min|mins|minute|minutes)\b/) || t.match(new RegExp('(?<![\\d-])(\\d{1,3})\\s*-?\\s*m\\s+' + chart));
